export const endUnprovenAccessQuery = `-- name: EndUnprovenAccess :one
WITH sessions AS (
	DELETE FROM "exagram"."sessions" WHERE user_id = $1::uuid RETURNING 1
), resets AS (
	DELETE FROM "exagram"."password_resets" WHERE user_id = $1::uuid RETURNING 1
), connections AS (
	UPDATE "exagram"."connections" SET revoked_at = now()
	WHERE user_id = $1::uuid AND revoked_at IS NULL
	RETURNING oidc_grant_id
), oidc AS (
	DELETE FROM "exagram"."oidc_payloads" o USING connections c
	WHERE c.oidc_grant_id IS NOT NULL AND (o.grant_id = c.oidc_grant_id OR (o.type = 'Grant' AND o.id = c.oidc_grant_id))
	RETURNING 1
), links AS (
	UPDATE "exagram"."links" SET revoked_at = now()
	WHERE created_by = $1::uuid AND revoked_at IS NULL
	RETURNING 1
), requests AS (
	DELETE FROM "exagram"."join_requests" r USING "exagram"."users" u
	WHERE u.id = $1::uuid AND (r.user_id = u.id OR (r.user_id IS NULL AND r.email = u.email))
		AND r.declined_at IS NULL
	RETURNING 1
), identities AS (
	DELETE FROM "exagram"."user_identities" WHERE user_id = $1::uuid RETURNING 1
)
SELECT (SELECT count(*) FROM sessions)::int AS sessions, (SELECT count(*) FROM resets)::int AS resets,
       (SELECT count(*) FROM connections)::int AS connections, (SELECT count(*) FROM oidc)::int AS oidc_payloads,
       (SELECT count(*) FROM links)::int AS links, (SELECT count(*) FROM requests)::int AS join_requests,
       (SELECT count(*) FROM identities)::int AS identities`;

export interface EndUnprovenAccessArgs {
    userId: string;
}

export interface EndUnprovenAccessRow {
    sessions: number;
    resets: number;
    connections: number;
    oidcPayloads: number;
    links: number;
    joinRequests: number;
    identities: number;
}

export async function endUnprovenAccess(sql: Sql, args: EndUnprovenAccessArgs): Promise<EndUnprovenAccessRow | null> {
    const rows = await sql.unsafe(endUnprovenAccessQuery, [args.userId]).values();
    if (rows.length !== 1) {
        return null;
    }
    const row = rows[0];
    if (!row) {
        return null;
    }
    return {
        sessions: row[0],
        resets: row[1],
        connections: row[2],
        oidcPayloads: row[3],
        links: row[4],
        joinRequests: row[5],
        identities: row[6]
    };
}

